function buildCall(kind) {
  const shapes = {
    content: ['prompt', 'user', 'call', 'content'],
    entity: ['prompt', 'user', 'call', 'entity(Class, spec?)'],
    stream: ['prompt', 'user', 'stream', 'content'],
    streamEntity: ['prompt', 'user', 'stream', 'collect', 'convert(BeanOutputConverter)'],
  };
  return shapes[kind] || null;
}
